<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\LeadMagnet; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class LeadMagnetController extends Controller { public function index(){return view('admin.lead_magnet.index',['leadMagnets'=>LeadMagnet::latest()->paginate(20)]);} public function create(){return view('admin.lead_magnet.form');} public function edit($id){return view('admin.lead_magnet.form',['leadMagnet'=>LeadMagnet::findOrFail($id)]);} public function store(Request $r){$r->validate(['name'=>'required|max:255','description'=>'nullable|string','file'=>'nullable|file|mimes:pdf|max:10240','cover'=>'nullable|image|max:5120']);$m=LeadMagnet::find($r->id); if(!$m && !$r->hasFile('file')) return back()->withErrors(['file'=>'PDF là bắt buộc.']); $data=['name'=>$r->name,'description'=>$r->description,'is_active'=>$r->boolean('is_active')]; if($r->hasFile('file')) $data['file_path']=$r->file('file')->store('lead-magnets','public'); if($r->hasFile('cover')) $data['cover_image']=$r->file('cover')->store('lead-magnets','public'); LeadMagnet::updateOrCreate(['id'=>$r->id],$data); return redirect()->route('admin.lead-magnet')->with('success','Đã lưu tài liệu.');} public function delete($id){$m=LeadMagnet::findOrFail($id); Storage::disk('public')->delete([$m->file_path,$m->cover_image]);$m->delete();return back()->with('success','Đã xóa tài liệu.');} }
